import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 문서번호 채번 규칙이 입력에 없어 'AD-일자-결재문서ID 6자리'로 부여한다.
// 가정: 상신 직후 상태는 결재대기, 첨부 소유 유형은 '결재문서'.
// 가정: 첨부 중복은 파일 내용 해시가 같은 첨부가 이미 있으면 차단한다 (범위는 확인 필요).
const STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];
const SUBMITTED_STATUS = '결재대기';
const OWNER_TYPE_APPROVAL = '결재문서';

function bad(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function intOf(value: unknown, label: string): number {
  const n = typeof value === 'number' ? value : typeof value === 'string' && value.trim() !== '' ? Number(value) : NaN;
  if (!Number.isInteger(n) || n <= 0) {
    throw bad(label + ' 값을 확인해 주세요.');
  }
  return n;
}

function textOf(value: unknown, label: string, max: number): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw bad(label + '을(를) 입력해 주세요.');
  }
  if (value.length > max) {
    throw bad(label + '은(는) ' + max + '자 이내로 입력해 주세요.');
  }
  return value;
}

function flagOf(value: unknown, label: string): boolean {
  if (value === undefined || value === null) {
    return false;
  }
  if (typeof value !== 'boolean') {
    throw bad(label + ' 값을 확인해 주세요.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr00307Controller {
  @Post('/approval-documents')
  @HttpCode(200)
  async createApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '시스템 관리자');
    const data = checks.inputOf(req.body);
    const formId = intOf(data['approvalFormId'], '결재양식');
    const title = textOf(data['title'], '문서 제목', 500);
    const businessType = textOf(data['linkedBusinessType'], '연계 업무 유형', 50);
    const businessId = intOf(data['linkedBusinessId'], '연계 업무 식별자');
    const body = typeof data['body'] === 'string' ? data['body'] : null;
    if (data['body'] !== undefined && data['body'] !== null && typeof data['body'] !== 'string') {
      throw bad('문서 본문 값을 확인해 주세요.');
    }
    const isUrgent = flagOf(data['isUrgent'], '긴급결재 여부');
    const isSecret = flagOf(data['isSecret'], '보안문서 여부');
    const rawIds = data['attachmentIds'];
    if (rawIds !== undefined && rawIds !== null && !Array.isArray(rawIds)) {
      throw bad('첨부파일 ID 목록 값을 확인해 주세요.');
    }
    const attachmentIds: number[] = (Array.isArray(rawIds) ? rawIds : []).map((v: unknown) => intOf(v, '첨부파일 ID'));
    return transaction(async (db) => {
      const forms = await db.query(
        'SELECT approval_form_id FROM approval_form WHERE approval_form_id = CAST(:formId AS bigint)',
        { formId },
      );
      if (forms.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '결재양식을 찾을 수 없습니다.');
      }
      const emps = await db.query(
        'SELECT department_id AS "departmentId" FROM employee WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      if (emps.length === 0 || emps[0]['departmentId'] === null) {
        throw bad('기안 부서가 지정되지 않아 상신할 수 없습니다.');
      }
      const created = await db.query(
        "INSERT INTO approval_document (approval_form_id, drafter_id, drafter_department_id, document_number, title, body, approval_status, is_urgent, is_secret, linked_business_type, linked_business_id, submitted_at, created_at, updated_at) VALUES (CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:deptId AS bigint), 'TMP-' || CAST(txid_current() AS text) || '-' || CAST(random() AS text), :title, :body, :status, :isUrgent, :isSecret, :businessType, CAST(:businessId AS bigint), now(), now(), now()) RETURNING approval_document_id AS "approvalDocumentId"",
        {
          formId,
          userId: user.id,
          deptId: emps[0]['departmentId'],
          title,
          body,
          status: SUBMITTED_STATUS,
          isUrgent,
          isSecret,
          businessType,
          businessId,
        },
      );
      const docId = created[0]['approvalDocumentId'];
      const numbered = await db.query(
        "UPDATE approval_document SET document_number = 'AD-' || to_char(now(), 'YYYYMMDD') || '-' || lpad(CAST(approval_document_id AS text), 6, '0'), updated_at = now() WHERE approval_document_id = CAST(:docId AS bigint) RETURNING approval_document_id AS \"approvalDocumentId\", document_number AS \"documentNumber\", approval_status AS \"approvalStatus\"",
        { docId },
      );
      for (const attachmentId of attachmentIds) {
        const linked = await db.execute(
          'UPDATE attachment SET owner_type = :ownerType, owner_id = CAST(:docId AS bigint), updated_at = now() WHERE attachment_id = CAST(:attachmentId AS bigint)',
          { ownerType: OWNER_TYPE_APPROVAL, docId, attachmentId },
        );
        if (linked === 0) {
          throw bad('첨부파일을 찾을 수 없습니다.');
        }
      }
      return numbered[0];
    });
  }

  @Post('/approval-documents/result')
  @HttpCode(200)
  async receiveApprovalResult(@Req() req: Request) {
    const user = currentUser(req);
    user.require('로그인 사용자');
    const data = checks.inputOf(req.body);
    const docId = intOf(data['approvalDocumentId'], '결재문서 ID');
    const status = data['approvalStatus'];
    if (typeof status !== 'string' || status.trim() === '') {
      throw bad('결재 진행 상태를 입력해 주세요.');
    }
    if (!STATUSES.includes(status)) {
      throw new ApiError(422, 'INVALID_APPROVAL_STATUS', '허용되지 않는 결재 상태입니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_document_id FROM approval_document WHERE approval_document_id = CAST(:docId AS bigint)',
        { docId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재문서를 찾을 수 없습니다.');
      }
      const rows = await db.query(
        "UPDATE approval_document SET approval_status = :status, completed_at = CASE WHEN :status = '완료' THEN now() ELSE completed_at END, updated_at = now() WHERE approval_document_id = CAST(:docId AS bigint) RETURNING approval_status AS \"approvalStatus\"",
        { status, docId },
      );
      return rows[0];
    });
  }

  @Post('/attachments')
  @HttpCode(200)
  async createAttachment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '시스템 관리자');
    const data = checks.inputOf(req.body);
    const file = textOf(data['file'], '업로드 파일', 255);
    let ownerType: string | null = null;
    if (data['ownerType'] !== undefined && data['ownerType'] !== null && data['ownerType'] !== '') {
      ownerType = textOf(data['ownerType'], '소유 대상 유형', 50);
    }
    let ownerId: number | null = null;
    if (data['ownerId'] !== undefined && data['ownerId'] !== null && data['ownerId'] !== '') {
      ownerId = intOf(data['ownerId'], '소유 대상 식별자');
    }
    return transaction(async (db) => {
      const same = await db.query(
        "SELECT attachment_id FROM attachment WHERE content_hash = encode(sha256(convert_to(:file, 'UTF8')), 'hex')",
        { file },
      );
      if (same.length > 0) {
        throw new ApiError(409, 'DUPLICATE_ATTACHMENT', '동일한 파일이 이미 등록되어 있습니다.');
      }
      const rows = await db.query(
        "INSERT INTO attachment (uploader_id, owner_type, owner_id, file_name, file_ext, file_size, content_hash, created_at, updated_at) VALUES (CAST(:userId AS bigint), :ownerType, CAST(:ownerId AS bigint), :file, substring(:file from '[.]([^.]+)$'), octet_length(convert_to(:file, 'UTF8')), encode(sha256(convert_to(:file, 'UTF8')), 'hex'), now(), now()) RETURNING attachment_id AS \"attachmentId\", file_name AS \"fileName\"",
        { userId: user.id, ownerType, ownerId, file },
      );
      return rows[0];
    });
  }
}

