import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  NumberInput,
  Select,
  Tiles,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

const STATUS_OPTIONS: [string, string][] = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'].map((s) => [s, s]);
const YES_NO: [string, string][] = [['N', '아니오'], ['Y', '예']];
const PENDING = ['결재대기', '진행중'];

export default function FnSfr00307Page({ role, notify }: PageProps) {
  const [docs, setDocs] = useState<Row[]>([]);
  const [atts, setAtts] = useState<Row[]>([]);
  const [mode, setMode] = useState<'' | 'doc' | 'att' | 'result'>('');
  const [target, setTarget] = useState<Row | null>(null);

  const [formId, setFormId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [bizType, setBizType] = useState('');
  const [bizId, setBizId] = useState<number | string>('');
  const [urgent, setUrgent] = useState('N');
  const [secret, setSecret] = useState('N');
  const [attId, setAttId] = useState('');

  const [file, setFile] = useState('');
  const [newStatus, setNewStatus] = useState('');

  function close() {
    setMode('');
    setTarget(null);
  }

  function openDoc() {
    setFormId('');
    setTitle('');
    setBody('');
    setBizType('');
    setBizId('');
    setUrgent('N');
    setSecret('N');
    setAttId('');
    setMode('doc');
  }

  function openAtt() {
    setFile('');
    setMode('att');
  }

  function openResult(row: Row) {
    setTarget(row);
    setNewStatus('');
    setMode('result');
  }

  async function submitDoc() {
    if (formId === '' || title.trim() === '' || bizType.trim() === '' || bizId === '') {
      throw new Error('결재양식, 문서 제목, 연계 업무 유형, 연계 업무 식별자를 입력해 주세요.');
    }
    const res = await call('POST', '/approval-documents', role, {
      approvalFormId: formId,
      title,
      body: body === '' ? undefined : body,
      linkedBusinessType: bizType,
      linkedBusinessId: bizId,
      isUrgent: urgent === 'Y',
      isSecret: secret === 'Y',
      attachmentIds: attId === '' ? [] : [Number(attId)],
    });
    setDocs([{ ...res, title, linkedBusinessType: bizType, linkedBusinessId: bizId }, ...docs]);
    notify('전자결재 문서를 상신했습니다.');
    close();
  }

  async function submitAtt() {
    if (file.trim() === '') {
      throw new Error('업로드 파일을 입력해 주세요.');
    }
    const res = await call('POST', '/attachments', role, { file });
    setAtts([res, ...atts]);
    notify('첨부파일을 등록했습니다.');
    close();
  }

  async function submitResult() {
    if (target === null) {
      return;
    }
    if (newStatus === '') {
      throw new Error('결재 진행 상태를 선택해 주세요.');
    }
    const res = await call('POST', '/approval-documents/result', role, {
      approvalDocumentId: target['approvalDocumentId'],
      approvalStatus: newStatus,
    });
    setDocs(docs.map((d) => (d['approvalDocumentId'] === target['approvalDocumentId'] ? { ...d, approvalStatus: res['approvalStatus'] } : d)));
    notify('결재 결과를 반영했습니다.');
    close();
  }

  const pendingCount = docs.filter((d) => PENDING.includes(String(d['approvalStatus']))).length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>상신 현황</h2>
        <Tiles
          items={[
            ['상신 문서', docs.length],
            ['결재 진행', pendingCount],
            ['등록 첨부', atts.length],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>상신 문서</h2>
        <Band total={docs.length}>
          <button onClick={openDoc}>상신</button>
          <button onClick={openAtt}>첨부 등록</button>
        </Band>
        <DataTable
          rows={docs}
          empty="상신한 문서가 없습니다."
          columns={[
            { key: 'documentNumber', label: '문서번호' },
            { key: 'title', label: '문서 제목' },
            { key: 'linkedBusinessType', label: '연계 업무 유형' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r['approvalStatus']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                PENDING.includes(String(r['approvalStatus'])) ? (
                  <button onClick={() => openResult(r)}>결과 반영</button>
                ) : null,
            },
          ]}
        />
      </section>
      <section className="box span-4">
        <h2>등록 첨부</h2>
        <DataTable
          rows={atts}
          empty="등록한 첨부파일이 없습니다."
          columns={[
            { key: 'attachmentId', label: '첨부파일 ID' },
            { key: 'fileName', label: '파일명' },
          ]}
        />
      </section>
      {mode === 'doc' && (
        <Drawer title="전자결재 상신" onClose={close}>
          <Form onSubmit={submitDoc} submit="상신">
            <Field label="결재양식" required>
              <LookupSelect table="approval_form" role={role} value={formId} onChange={setFormId} />
            </Field>
            <Field label="문서 제목" required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="문서 본문" wide>
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
            <Field label="연계 업무 유형" required>
              <TextInput value={bizType} onChange={setBizType} />
            </Field>
            <Field label="연계 업무 식별자" required>
              <NumberInput value={bizId} onChange={setBizId} />
            </Field>
            <Field label="긴급결재 여부">
              <Select value={urgent} onChange={setUrgent} options={YES_NO} placeholder="선택" />
            </Field>
            <Field label="보안문서 여부">
              <Select value={secret} onChange={setSecret} options={YES_NO} placeholder="선택" />
            </Field>
            <Field label="첨부파일" hint="이 화면에서 등록한 첨부파일 중 선택합니다.">
              <Select
                value={attId}
                onChange={setAttId}
                options={atts.map((a): [string, string] => [String(a['attachmentId']), String(a['fileName'])])}
                placeholder="선택 안 함"
              />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'att' && (
        <Drawer title="첨부 등록" onClose={close}>
          <Form onSubmit={submitAtt} submit="등록">
            <Field label="업로드 파일" required wide>
              <TextInput value={file} onChange={setFile} />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'result' && target !== null && (
        <Drawer title="결재 결과 반영" onClose={close}>
          <Form onSubmit={submitResult} submit="반영">
            <Field label="문서번호">
              <span>{String(target['documentNumber'] ?? '')}</span>
            </Field>
            <Field label="결재 진행 상태" required>
              <Select value={newStatus} onChange={setNewStatus} options={STATUS_OPTIONS} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
